-- Arduino LED Matrix Maze Game (slug 25).
-- New unpublished project. Does not change projects 8, 18, 23, or 24.
-- Does not delete user progress.

do $$
begin
  if exists (
    select 1 from public.projects
    where slug = '25' and title <> 'Arduino LED Matrix Maze Game'
  ) then
    raise exception 'slug 25 already belongs to a different project';
  end if;
end;
$$;

update public.components
set description = 'Assembled FC-16 MAX7219 8×8 module with a five-pin male input header. With that header on the right, top to bottom is CLK, CS, DIN, GND, VCC. Runs at 5 V. Use the MD_MAX72XX hardware type FC16_HW.'
where slug = 'max7219';

update public.components
set description = 'Preassembled two-axis joystick with five male pins. Usual silk order is GND, +5V, VRx, VRy, SW. The switch connects to ground when pressed. Follow the silk if a board prints a different order.'
where slug = 'joystick';

insert into public.component_capabilities (component_id, capability, value)
select component.id, spec.capability, spec.value
from (
  values
    ('max7219', 'function', 'led_matrix'),
    ('max7219', 'supply_v', '5'),
    ('max7219', 'interface', 'spi'),
    ('max7219', 'physical_form', 'fc16_male_header'),
    ('joystick', 'supply_v', '5'),
    ('joystick', 'physical_form', 'five_pin_male')
) as spec(slug, capability, value)
join public.components as component on component.slug = spec.slug
on conflict (component_id, capability, value) do nothing;

insert into public.projects (
  slug, title, description, overview, category, difficulty, duration_label, image_key, learning_objectives, sort_order, is_published
)
values (
  '25',
  'Arduino LED Matrix Maze Game',
  'Guide a blinking dot through five mazes on an 8×8 LED matrix.',
  'An Arduino Uno, an FC-16 MAX7219 matrix, and a five-pin joystick. The stick moves one square at a time. Walls block the way. The Serial Monitor prints each level time.',
  'displays',
  'intermediate',
  '3 hrs',
  'ledMatrixMaze',
  array[
    'Wire an FC-16 MAX7219 matrix and a five-pin joystick to an Arduino Uno',
    'Share 5 V and ground on a breadboard without a second supply',
    'Move one dot through five fixed mazes with a deadzone and a debounced button',
    'Read a level time from millis() in the Serial Monitor'
  ],
  25,
  false
)
on conflict (slug) do update
set
  title = excluded.title,
  description = excluded.description,
  overview = excluded.overview,
  category = excluded.category,
  difficulty = excluded.difficulty,
  duration_label = excluded.duration_label,
  image_key = excluded.image_key,
  learning_objectives = excluded.learning_objectives,
  sort_order = excluded.sort_order,
  is_published = false;

delete from public.project_components
where project_id = (select id from public.projects where slug = '25');

insert into public.project_components (project_id, component_id, quantity, sort_order)
values
  ((select id from public.projects where slug = '25'), (select id from public.components where slug = 'arduino-uno-r3'), 1, 1),
  ((select id from public.projects where slug = '25'), (select id from public.components where slug = 'max7219'), 1, 2),
  ((select id from public.projects where slug = '25'), (select id from public.components where slug = 'joystick'), 1, 3),
  ((select id from public.projects where slug = '25'), (select id from public.components where slug = 'breadboard'), 1, 4),
  ((select id from public.projects where slug = '25'), (select id from public.components where slug = 'jumper-wires'), 12, 5),
  ((select id from public.projects where slug = '25'), (select id from public.components where slug = 'usb-data-cable'), 1, 6),
  ((select id from public.projects where slug = '25'), (select id from public.components where slug = 'usb-power-source'), 1, 7);

insert into public.project_requirements (
  project_id, project_component_id, role, substitution_policy, sort_order
)
select p.id, pc.id, v.role, 'exact', pc.sort_order
from public.projects p
join public.project_components pc on pc.project_id = p.id
join public.components c on c.id = pc.component_id
join (
  values
    ('arduino-uno-r3', 'microcontroller'),
    ('max7219', 'display'),
    ('joystick', 'input'),
    ('breadboard', 'breadboard'),
    ('jumper-wires', 'jumper_wires'),
    ('usb-data-cable', 'usb_cable'),
    ('usb-power-source', 'usb_power')
) as v(slug, role) on v.slug = c.slug
where p.slug = '25'
on conflict (project_component_id) do update
set
  role = excluded.role,
  substitution_policy = excluded.substitution_policy,
  sort_order = excluded.sort_order;

insert into public.project_requirement_constraints (requirement_id, capability, value)
select r.id, v.capability, v.value
from public.project_requirements r
join public.project_components pc on pc.id = r.project_component_id
join public.projects p on p.id = r.project_id
join public.components c on c.id = pc.component_id
join (
  values
    ('arduino-uno-r3', 'function', 'development_board'),
    ('arduino-uno-r3', 'logic_level_v', '5'),
    ('arduino-uno-r3', 'header_profile', 'uno_r3'),
    ('max7219', 'function', 'led_matrix'),
    ('max7219', 'supply_v', '5'),
    ('max7219', 'interface', 'spi'),
    ('max7219', 'physical_form', 'fc16_male_header'),
    ('joystick', 'function', 'joystick'),
    ('joystick', 'supply_v', '5'),
    ('joystick', 'physical_form', 'five_pin_male'),
    ('jumper-wires', 'physical_form', 'male_male')
) as v(slug, capability, value) on v.slug = c.slug
where p.slug = '25'
on conflict (requirement_id, capability, value) do nothing;

delete from public.project_steps
where project_id = (select id from public.projects where slug = '25');

insert into public.project_steps (
  project_id, sort_order, stage_sort_order, stage_title, title, description, tip, blocks
)
select p.id, v.sort_order, v.stage_sort_order, v.stage_title, v.title, v.description, v.tip, v.blocks::jsonb
from public.projects p
cross join (
  values
  (0, 0, $mazestep$Understand the project$mazestep$, $mazestep$What you are building$mazestep$, $mazestep$A joystick moves one dot through five mazes on an 8×8 LED matrix.$mazestep$, null, $mazestep$[{"type":"components","heading":"Parts","items":[{"id":"arduino-uno-r3","name":"Arduino Uno R3","illustrationId":"arduino-uno","owned":false,"quantity":1},{"id":"max7219","name":"MAX7219 8×8 LED matrix","illustrationId":"led-matrix","owned":false,"quantity":1},{"id":"joystick","name":"Analog joystick module","illustrationId":"joystick","owned":false,"quantity":1},{"id":"breadboard","name":"Breadboard","illustrationId":"breadboard","owned":false,"quantity":1},{"id":"jumper-wires","name":"Male-to-male jumper wires","illustrationId":"jumper-wires","owned":false,"quantity":12},{"id":"usb-data-cable","name":"USB data cable","illustrationId":"usb-cable","owned":false,"quantity":1},{"id":"usb-power-source","name":"USB power source","illustrationId":"generic-module","owned":false,"quantity":1}]},{"type":"text","heading":"The game","body":"The player is one blinking LED. Solid LEDs are walls. The goal blinks more slowly than the player. Push the joystick to move one square. A wall or the edge of the grid stops the move. Reaching the goal finishes that level and the next maze appears. The joystick button restarts the current level. After level 5, one LED runs around the border and the button starts again at level 1."},{"type":"text","heading":"How you will build it","body":"First you will share the Uno 5 V and GND pins with both modules on a breadboard. Then you will connect three matrix signals and three joystick signals. The sketch uses the MD_MAX72XX library with the FC-16 hardware type. The same pin numbers appear in the wiring and in the program."},{"type":"expected","heading":"What done looks like","body":"Five mazes can be finished with the stick. The Serial Monitor at 9600 baud prints each level time in milliseconds, and the total when level 5 is finished. The matrix stays readable: walls are steady, the player blinks quickly, and the goal blinks slowly."}]$mazestep$),
  (1, 0, $mazestep$Understand the project$mazestep$, $mazestep$How the display shows the maze$mazestep$, $mazestep$One colour has to stand for walls, the player, and the goal.$mazestep$, null, $mazestep$[{"type":"text","heading":"Orientation","body":"This project uses an assembled FC-16 MAX7219 module. Seat it so the five-pin input header is on the right. From the top of that header the names are CLK, CS, DIN, GND, and VCC. With the header on the right, row 0 is the top of the grid and column 0 is the left. The library call setPoint(row, column) uses that same order. PCB text may look upside down in this orientation. That is the FC-16 mounting the library expects."},{"type":"text","heading":"What each LED means","body":"A wall LED stays on. The goal is on for most of each 800 ms period and off for the rest, so it winks slowly. The player is on for 120 ms and off for 120 ms. If the player stands on the goal, the player blink wins, so the goal does not show through the player. Empty squares stay off. The sketch draws walls first, then the goal, then the player."},{"type":"tip","body":"The five mazes are written into the sketch. They are not generated at random, so the same level is the same maze every time you play."}]$mazestep$),
  (2, 0, $mazestep$Understand the project$mazestep$, $mazestep$Meet the modules$mazestep$, $mazestep$Both modules are already assembled. You are matching silk labels, not soldering a header.$mazestep$, null, $mazestep$[{"type":"text","heading":"MAX7219 matrix","body":"Use a fully assembled FC-16 style board: one MAX7219 and one 8×8 matrix, with a 5-pin male input header. The Uno has 5 V logic, which meets the MAX7219 high-level input. Do not power this module from the Uno 3.3 V pin. A common module sets the LED current with a resistor near 10 kΩ. The MAX7219 datasheet minimum of 9.53 kΩ allows about 40 mA through one segment. Eight LEDs in one row can therefore ask for a few hundred milliamps if they are all fully lit. This maze never lights all 64 LEDs, and the sketch keeps the library intensity at 2 on a scale of 0 to 15. That is the reason a computer USB port can supply the board. Do not turn intensity up to 15."},{"type":"text","heading":"Joystick","body":"Use a preassembled two-axis module with five male pins, the kind sold as KY-023 or a PS2-style stick. The usual silk order is GND, +5V, VRx, VRy, and SW. VRx and VRy rest near the middle of the 0 to 1023 analog range. SW is a pushbutton that connects to GND when pressed. The sketch uses INPUT_PULLUP, so an unpressed button reads HIGH. If your silk prints a different order, follow the silk and not this sentence."}]$mazestep$),
  (3, 1, $mazestep$Build the circuit$mazestep$, $mazestep$Place the Uno and the breadboard$mazestep$, $mazestep$The Uno stays beside the breadboard. Its female headers take male jumper pins.$mazestep$, null, $mazestep$[{"type":"text","heading":"Placement","body":"Put the Uno on the left with the USB socket toward you and the digital header facing the breadboard. Put a breadboard on the right. Leave USB unplugged. The Uno has one 5 V pin, and both modules need 5 V and GND, so the breadboard power rails are the distribution. Do not twist two jumpers into one header pin."},{"type":"wiring","heading":"Boards in place","nodes":[{"id":"arduino","name":"Arduino Uno","illustrationId":"arduino-uno"}],"connections":[],"assembly":{"parts":[],"jumpers":[]}},{"type":"expected","heading":"Check","body":"The Uno and the breadboard are side by side, USB is unplugged, and no module is inserted yet."}]$mazestep$),
  (4, 1, $mazestep$Build the circuit$mazestep$, $mazestep$Share 5 V and GND$mazestep$, $mazestep$Two male-to-male jumpers feed the left breadboard rails from the Uno.$mazestep$, $mazestep$Both jumpers are male-to-male. One end is in the Uno female header. The other end is in the rail.$mazestep$, $mazestep$[{"type":"text","heading":"Rails","body":"Jumper the Uno 5 V pin to the left red rail, row 1. Jumper the Uno GND pin beside it to the left blue rail, row 1. Later steps take module power from those rails. The red rail is Uno 5 V. The blue rail is Uno ground. Do not connect the 3.3 V pin."},{"type":"wiring","heading":"Power into the rails","nodes":[{"id":"arduino","name":"Arduino Uno","illustrationId":"arduino-uno"}],"connections":[],"assembly":{"parts":[],"jumpers":["uno-5v","uno-gnd"]}},{"type":"warning","body":"Keep the matrix intensity at the value in the sketch. Lighting every LED at full brightness can pull more current than a weak USB port will give. This game does not do that."}]$mazestep$),
  (5, 1, $mazestep$Build the circuit$mazestep$, $mazestep$Seat the matrix and power it$mazestep$, $mazestep$The five male pins go into column c, rows 1 to 5, with the input header on the right.$mazestep$, $mazestep$If the silk on your FC-16 board names the pins in another order, follow the silk and move these two power jumpers with GND and VCC.$mazestep$, $mazestep$[{"type":"text","heading":"Pin order","body":"Press the FC-16 input header into column c. Row 1 is CLK, row 2 is CS, row 3 is DIN, row 4 is GND, and row 5 is VCC. The header is on the right of the module. Jumper the blue rail, row 4, to column a row 4. Jumper the red rail, row 5, to column a row 5. Column a and column c on the same number are already connected inside the breadboard, so those two jumpers power the module."},{"type":"wiring","heading":"Matrix power","nodes":[{"id":"arduino","name":"Arduino Uno","illustrationId":"arduino-uno"},{"id":"matrix","name":"LED Matrix","illustrationId":"led-matrix"}],"connections":[{"fromComponent":"Arduino Uno","fromPin":"5V","toComponent":"LED Matrix","toPin":"VCC","signal":"power"},{"fromComponent":"Arduino Uno","fromPin":"GND","toComponent":"LED Matrix","toPin":"GND","signal":"ground"}],"assembly":{"parts":["matrix"],"jumpers":["matrix-gnd","matrix-vcc"]}}]$mazestep$),
  (6, 1, $mazestep$Build the circuit$mazestep$, $mazestep$Connect CLK, CS, and DIN$mazestep$, $mazestep$Three signal jumpers match the pins in the sketch.$mazestep$, null, $mazestep$[{"type":"text","heading":"Signals","body":"Jumper Uno D13 to column a row 1, which is CLK. Jumper Uno D10 to column a row 2, which is CS. Jumper Uno D11 to column a row 3, which is DIN. D11 is the data pin the library calls DIN. D13 is the clock. D10 is chip select, also labelled LOAD or CS on some boards."},{"type":"wiring","heading":"Matrix signals","nodes":[{"id":"arduino","name":"Arduino Uno","illustrationId":"arduino-uno"},{"id":"matrix","name":"LED Matrix","illustrationId":"led-matrix"}],"connections":[{"fromComponent":"Arduino Uno","fromPin":"D13","toComponent":"LED Matrix","toPin":"CLK","signal":"signal"},{"fromComponent":"Arduino Uno","fromPin":"D10","toComponent":"LED Matrix","toPin":"CS","signal":"signal"},{"fromComponent":"Arduino Uno","fromPin":"D11","toComponent":"LED Matrix","toPin":"DIN","signal":"signal"}],"assembly":{"parts":[],"jumpers":["matrix-clk","matrix-cs","matrix-din"]}},{"type":"connections","summary":"D13 CLK · D10 CS · D11 DIN","rows":[{"fromComponent":"Arduino Uno","fromPin":"D13","toComponent":"LED Matrix","toPin":"CLK","signal":"signal"},{"fromComponent":"Arduino Uno","fromPin":"D10","toComponent":"LED Matrix","toPin":"CS","signal":"signal"},{"fromComponent":"Arduino Uno","fromPin":"D11","toComponent":"LED Matrix","toPin":"DIN","signal":"signal"}]}]$mazestep$),
  (7, 1, $mazestep$Build the circuit$mazestep$, $mazestep$Seat the joystick and power it$mazestep$, $mazestep$The joystick header uses rows 8 to 12, below the matrix.$mazestep$, null, $mazestep$[{"type":"text","heading":"Header","body":"Press the joystick male header into column c. Row 8 is GND, row 9 is +5V, row 10 is VRx, row 11 is VRy, and row 12 is SW. Jumper the blue rail, row 8, to column a row 8. Jumper the red rail, row 9, to column a row 9. The stick and the matrix now share the same 5 V and ground rails."},{"type":"wiring","heading":"Joystick power","nodes":[{"id":"arduino","name":"Arduino Uno","illustrationId":"arduino-uno"},{"id":"joystick","name":"Joystick","illustrationId":"joystick"}],"connections":[{"fromComponent":"Arduino Uno","fromPin":"5V","toComponent":"Joystick","toPin":"+5V","signal":"power"},{"fromComponent":"Arduino Uno","fromPin":"GND","toComponent":"Joystick","toPin":"GND","signal":"ground"}],"assembly":{"parts":["joystick"],"jumpers":["joy-gnd","joy-5v"]}}]$mazestep$),
  (8, 1, $mazestep$Build the circuit$mazestep$, $mazestep$Connect VRx, VRy, and SW$mazestep$, $mazestep$The stick uses two analog pins and one digital pin.$mazestep$, null, $mazestep$[{"type":"text","heading":"Signals","body":"Jumper Uno A0 to column a row 10, which is VRx. Jumper Uno A1 to column a row 11, which is VRy. Jumper Uno D2 to column a row 12, which is SW. Leave the stick centred while you insert the wires so you do not bend the header."},{"type":"wiring","heading":"Joystick signals","nodes":[{"id":"arduino","name":"Arduino Uno","illustrationId":"arduino-uno"},{"id":"joystick","name":"Joystick","illustrationId":"joystick"}],"connections":[{"fromComponent":"Arduino Uno","fromPin":"A0","toComponent":"Joystick","toPin":"VRx","signal":"signal"},{"fromComponent":"Arduino Uno","fromPin":"A1","toComponent":"Joystick","toPin":"VRy","signal":"signal"},{"fromComponent":"Arduino Uno","fromPin":"D2","toComponent":"Joystick","toPin":"SW","signal":"signal"}],"assembly":{"parts":[],"jumpers":["joy-x","joy-y","joy-sw"]}},{"type":"connections","summary":"A0 VRx · A1 VRy · D2 SW","rows":[{"fromComponent":"Arduino Uno","fromPin":"A0","toComponent":"Joystick","toPin":"VRx","signal":"signal"},{"fromComponent":"Arduino Uno","fromPin":"A1","toComponent":"Joystick","toPin":"VRy","signal":"signal"},{"fromComponent":"Arduino Uno","fromPin":"D2","toComponent":"Joystick","toPin":"SW","signal":"signal"}]}]$mazestep$),
  (9, 1, $mazestep$Build the circuit$mazestep$, $mazestep$Check every connection$mazestep$, $mazestep$Count 12 male-to-male jumpers before you plug in USB.$mazestep$, null, $mazestep$[{"type":"wiring","heading":"Complete circuit","nodes":[{"id":"arduino","name":"Arduino Uno","illustrationId":"arduino-uno"},{"id":"matrix","name":"LED Matrix","illustrationId":"led-matrix"},{"id":"joystick","name":"Joystick","illustrationId":"joystick"}],"connections":[{"fromComponent":"Arduino Uno","fromPin":"5V","toComponent":"LED Matrix","toPin":"VCC","signal":"power"},{"fromComponent":"Arduino Uno","fromPin":"GND","toComponent":"LED Matrix","toPin":"GND","signal":"ground"},{"fromComponent":"Arduino Uno","fromPin":"5V","toComponent":"Joystick","toPin":"+5V","signal":"power"},{"fromComponent":"Arduino Uno","fromPin":"GND","toComponent":"Joystick","toPin":"GND","signal":"ground"},{"fromComponent":"Arduino Uno","fromPin":"D13","toComponent":"LED Matrix","toPin":"CLK","signal":"signal"},{"fromComponent":"Arduino Uno","fromPin":"D10","toComponent":"LED Matrix","toPin":"CS","signal":"signal"},{"fromComponent":"Arduino Uno","fromPin":"D11","toComponent":"LED Matrix","toPin":"DIN","signal":"signal"},{"fromComponent":"Arduino Uno","fromPin":"A0","toComponent":"Joystick","toPin":"VRx","signal":"signal"},{"fromComponent":"Arduino Uno","fromPin":"A1","toComponent":"Joystick","toPin":"VRy","signal":"signal"},{"fromComponent":"Arduino Uno","fromPin":"D2","toComponent":"Joystick","toPin":"SW","signal":"signal"}]},{"type":"connections","heading":"Every electrical connection","summary":"Matrix DIN D11 · CLK D13 · CS D10 · joystick A0 A1 D2 · shared 5 V and GND","rows":[{"fromComponent":"Arduino Uno","fromPin":"5V","toComponent":"LED Matrix","toPin":"VCC","signal":"power"},{"fromComponent":"Arduino Uno","fromPin":"GND","toComponent":"LED Matrix","toPin":"GND","signal":"ground"},{"fromComponent":"Arduino Uno","fromPin":"5V","toComponent":"Joystick","toPin":"+5V","signal":"power"},{"fromComponent":"Arduino Uno","fromPin":"GND","toComponent":"Joystick","toPin":"GND","signal":"ground"},{"fromComponent":"Arduino Uno","fromPin":"D13","toComponent":"LED Matrix","toPin":"CLK","signal":"signal"},{"fromComponent":"Arduino Uno","fromPin":"D10","toComponent":"LED Matrix","toPin":"CS","signal":"signal"},{"fromComponent":"Arduino Uno","fromPin":"D11","toComponent":"LED Matrix","toPin":"DIN","signal":"signal"},{"fromComponent":"Arduino Uno","fromPin":"A0","toComponent":"Joystick","toPin":"VRx","signal":"signal"},{"fromComponent":"Arduino Uno","fromPin":"A1","toComponent":"Joystick","toPin":"VRy","signal":"signal"},{"fromComponent":"Arduino Uno","fromPin":"D2","toComponent":"Joystick","toPin":"SW","signal":"signal"}]},{"type":"test","heading":"What to verify","body":"CLK, CS, DIN, GND, and VCC each have one row. GND and +5V of the joystick each have one row. VRx is only A0, VRy is only A1, and SW is only D2. No jumper is in the 3.3 V pin. You have used 12 male-to-male jumpers and no male-to-female jumpers. USB is still unplugged."}]$mazestep$),
  (10, 2, $mazestep$Prepare the software$mazestep$, $mazestep$Install the IDE, the board, and the library$mazestep$, $mazestep$The sketch targets an Arduino Uno and MD_MAX72XX 3.5.1.$mazestep$, null, $mazestep$[{"type":"text","heading":"Board","body":"Install the Arduino IDE from arduino.cc. Open Tools, Board, Arduino AVR Boards, and choose Arduino Uno. Plug the USB data cable into the Uno and the computer. Open Tools, Port, and select the port that appears. Unplug the cable once: the correct port is the one that disappears. A charge-only cable can light the power LED and still never show a port."},{"type":"text","heading":"Library","body":"Open Tools, Manage Libraries, search for MD_MAX72XX by MajicDesigns, and install version 3.5.1. The sketch includes MD_MAX72xx.h and constructs the display as FC16_HW with data on pin 11, clock on pin 13, and chip select on pin 10. Do not install a different MAX7219 library and expect this sketch to compile."},{"type":"expected","heading":"Check","body":"The board menu says Arduino Uno, a serial port is selected, and Library Manager shows MD_MAX72XX 3.5.1 installed."}]$mazestep$),
  (11, 2, $mazestep$Prepare the software$mazestep$, $mazestep$Turn on one LED$mazestep$, $mazestep$The setup function lights row 0, column 0, then clears it. That is the matrix test.$mazestep$, null, $mazestep$[{"type":"text","heading":"What this does","body":"setPoint(0, 0, true) is row 0 and column 0, the top-left LED when the FC-16 input header is on the right. update() sends the buffer to the chip. Intensity is set to 2 before this runs. After a short pause the same LED turns off and level 1 is drawn. You will paste the whole sketch in a later step. This is the part that proves the matrix is alive."},{"type":"code","language":"Arduino","filename":"led_matrix_maze.ino","libraries":["MD_MAX72XX 3.5.1"],"code":"  display.setPoint(0, 0, true);\n  display.update();\n  delay(300);\n  display.clear();\n  display.update();"},{"type":"code_explanation","body":"If that corner never lights, the usual causes are a blank intensity, CLK and DIN swapped, or the module oriented with the input header on the left. The troubleshooting step at the end covers those cases. Do not add a second display library."}]$mazestep$),
  (12, 2, $mazestep$Prepare the software$mazestep$, $mazestep$Read a direction from the stick$mazestep$, $mazestep$A centred stick is ignored. A diagonal follows the stronger axis.$mazestep$, null, $mazestep$[{"type":"text","heading":"Deadzone","body":"Each axis rests near 512. Anything within 80 counts of 512 is centre, so small noise does not move the player. Past that band, the sign of the reading becomes one grid step, either -1 or +1. INVERT_Y starts true, so a rising VRy reading moves toward row 0, the top of the matrix. INVERT_X starts false. If your module faces the other way, you change those two booleans and nothing else."},{"type":"text","heading":"Diagonals","body":"If both axes leave the deadzone, the sketch keeps the axis with the larger distance from 512 and clears the other. If the two distances are equal, it moves neither axis. One deliberate push therefore makes one horizontal or vertical step, not a diagonal jump."},{"type":"code","language":"Arduino","filename":"led_matrix_maze.ino","libraries":["MD_MAX72XX 3.5.1"],"code":"int axisDirection(int raw, bool invert) {\n  int offset = raw - JOY_CENTER;\n  if (abs(offset) <= JOY_DEADZONE) {\n    return 0;\n  }\n  int sign = offset > 0 ? 1 : -1;\n  return invert ? -sign : sign;\n}\n\nvoid stickStep(int xRaw, int yRaw, int &dx, int &dy) {\n  dx = axisDirection(xRaw, INVERT_X);\n  dy = axisDirection(yRaw, INVERT_Y);\n  if (dx != 0 && dy != 0) {\n    int xMag = abs(xRaw - JOY_CENTER);\n    int yMag = abs(yRaw - JOY_CENTER);\n    if (xMag == yMag) {\n      dx = 0;\n      dy = 0;\n    } else if (xMag > yMag) {\n      dy = 0;\n    } else {\n      dx = 0;\n    }\n  }\n}"}]$mazestep$),
  (13, 3, $mazestep$Build the game$mazestep$, $mazestep$Store the player and the walls$mazestep$, $mazestep$A wall is a bit in an 8-byte row. The player is two integers.$mazestep$, null, $mazestep$[{"type":"text","heading":"Levels","body":"WALLS holds five mazes. Each maze is eight bytes, one per row. Bit 0 of a byte is column 0, the left column. A set bit is a wall. START_X and START_Y are the open square where the player appears. GOAL_X and GOAL_Y are the open square the player has to reach. beginLevel copies the start of the chosen maze into playerX and playerY and prints the level number. tryStep refuses a move that would leave the 8×8 grid or land on a wall."},{"type":"code","language":"Arduino","filename":"led_matrix_maze.ino","libraries":["MD_MAX72XX 3.5.1"],"code":"void beginLevel(int index) {\n  levelIndex = index;\n  playerX = START_X[index];\n  playerY = START_Y[index];\n  phase = 'p';\n  levelStarted = millis();\n  holdX = 0;\n  holdY = 0;\n  holdSince = levelStarted;\n  lastMove = 0;\n  Serial.print(\"Level \");\n  Serial.println(index + 1);\n}\n\nbool tryStep(int dx, int dy) {\n  if (dx == 0 && dy == 0) {\n    return false;\n  }\n  int nextX = playerX + dx;\n  int nextY = playerY + dy;\n  if (wallAt(levelIndex, nextX, nextY)) {\n    return false;\n  }\n  playerX = nextX;\n  playerY = nextY;\n  return true;\n}"},{"type":"code_explanation","body":"The five mazes get harder, and each one has a route from its start to its goal. The button calls beginLevel again for the maze you are already on, which puts the player back on the start square."}]$mazestep$),
  (14, 3, $mazestep$Build the game$mazestep$, $mazestep$Move one square at a time$mazestep$, $mazestep$Holding the stick repeats. A tap does not fire twice.$mazestep$, null, $mazestep$[{"type":"text","heading":"Repeat","body":"The first time the stick leaves centre, the player moves one square. Holding the same direction does nothing until 280 ms have passed, then it repeats every 180 ms. Releasing the stick clears that hold, so the next push moves immediately. The loop never calls delay, so the button and the blink stay responsive while you hold the stick."},{"type":"text","heading":"Drawing","body":"drawPlay clears the matrix and walks every square. A wall turns on. The goal replaces that decision with a slow blink. The player replaces both with a fast blink. setPoint uses the row as the first argument and the column as the second, matching the FC-16 orientation from the first stage."},{"type":"code","language":"Arduino","filename":"led_matrix_maze.ino","libraries":["MD_MAX72XX 3.5.1"],"code":"void drawPlay(unsigned long now) {\n  display.clear();\n  for (int y = 0; y < GRID; y++) {\n    for (int x = 0; x < GRID; x++) {\n      bool on = wallAt(levelIndex, x, y);\n      if (x == GOAL_X[levelIndex] && y == GOAL_Y[levelIndex]) {\n        on = (now % 800) < 600;\n      }\n      if (x == playerX && y == playerY) {\n        on = (now % 240) < 120;\n      }\n      if (on) {\n        display.setPoint(y, x, true);\n      }\n    }\n  }\n  display.update();\n}"}]$mazestep$),
  (15, 3, $mazestep$Build the game$mazestep$, $mazestep$Finish a level and keep the time$mazestep$, $mazestep$millis() measures the level. The matrix does not try to draw digits.$mazestep$, null, $mazestep$[{"type":"text","heading":"Goal","body":"When a move lands on the goal, the sketch prints the level number and the milliseconds since that level started. Levels 1 to 4 then play a short flash of the player and the goal for 700 ms and load the next maze. Level 5 prints the total milliseconds since the run started and changes to the border chase. There is no second screen for the clock. The Serial Monitor at 9600 baud is the timer."},{"type":"text","heading":"Button","body":"SW uses the internal pull-up. The sketch treats LOW as pressed. A press counts only after it has stayed down for 40 ms, and holding the button does not retrigger. During a level, the press restarts that level. During the final chase, the press returns to level 1 and starts the total time again."},{"type":"tip","body":"Open the Serial Monitor after upload. A centred stick prints nothing. An accepted step prints move, the direction, and the raw analog pair."}]$mazestep$),
  (16, 3, $mazestep$Build the game$mazestep$, $mazestep$Upload the complete sketch$mazestep$, $mazestep$This is the whole program. It replaces anything already in the editor.$mazestep$, null, $mazestep$[{"type":"code","language":"Arduino","filename":"led_matrix_maze.ino","libraries":["MD_MAX72XX 3.5.1"],"code":"#include <MD_MAX72xx.h>\n\nconst int DIN_PIN = 11;\nconst int CLK_PIN = 13;\nconst int CS_PIN = 10;\nconst int X_PIN = A0;\nconst int Y_PIN = A1;\nconst int SW_PIN = 2;\n\nconst int JOY_CENTER = 512;\nconst int JOY_DEADZONE = 80;\nconst bool INVERT_X = false;\nconst bool INVERT_Y = true;\nconst unsigned long MOVE_ARM_MS = 280;\nconst unsigned long MOVE_REPEAT_MS = 180;\nconst unsigned long BUTTON_DEBOUNCE_MS = 40;\nconst unsigned long SUCCESS_MS = 700;\nconst int GRID = 8;\nconst int LEVEL_COUNT = 5;\n\nMD_MAX72XX display(MD_MAX72XX::FC16_HW, DIN_PIN, CLK_PIN, CS_PIN, 1);\n\nconst uint8_t WALLS[LEVEL_COUNT][GRID] = {\n  { 0xff, 0x81, 0xbd, 0x81, 0xbd, 0x81, 0x81, 0xff },\n  { 0xff, 0x81, 0x9f, 0x81, 0xbd, 0x85, 0xa5, 0xff },\n  { 0xff, 0x85, 0xb5, 0xa5, 0xad, 0xa1, 0xaf, 0xff },\n  { 0xff, 0x91, 0xd5, 0x95, 0xb5, 0x85, 0xbd, 0xff },\n  { 0xff, 0x95, 0xd5, 0x91, 0xb7, 0xa1, 0x8d, 0xff }\n};\nconst uint8_t START_X[LEVEL_COUNT] = { 1, 1, 1, 5, 1 };\nconst uint8_t START_Y[LEVEL_COUNT] = { 1, 1, 1, 1, 1 };\nconst uint8_t GOAL_X[LEVEL_COUNT] = { 6, 6, 6, 1, 5 };\nconst uint8_t GOAL_Y[LEVEL_COUNT] = { 6, 6, 6, 6, 6 };\n\nint levelIndex = 0;\nint playerX = 0;\nint playerY = 0;\nchar phase = 'p';\nunsigned long levelStarted = 0;\nunsigned long runStarted = 0;\nunsigned long successStarted = 0;\nint holdX = 0;\nint holdY = 0;\nunsigned long holdSince = 0;\nunsigned long lastMove = 0;\nbool buttonDown = false;\nunsigned long buttonChanged = 0;\n\n// region: direction\nint axisDirection(int raw, bool invert) {\n  int offset = raw - JOY_CENTER;\n  if (abs(offset) <= JOY_DEADZONE) {\n    return 0;\n  }\n  int sign = offset > 0 ? 1 : -1;\n  return invert ? -sign : sign;\n}\n\nvoid stickStep(int xRaw, int yRaw, int &dx, int &dy) {\n  dx = axisDirection(xRaw, INVERT_X);\n  dy = axisDirection(yRaw, INVERT_Y);\n  if (dx != 0 && dy != 0) {\n    int xMag = abs(xRaw - JOY_CENTER);\n    int yMag = abs(yRaw - JOY_CENTER);\n    if (xMag == yMag) {\n      dx = 0;\n      dy = 0;\n    } else if (xMag > yMag) {\n      dy = 0;\n    } else {\n      dx = 0;\n    }\n  }\n}\n// end: direction\n\nbool wallAt(int index, int x, int y) {\n  if (x < 0 || y < 0 || x >= GRID || y >= GRID) {\n    return true;\n  }\n  return (WALLS[index][y] & (1 << x)) != 0;\n}\n\n// region: player\nvoid beginLevel(int index) {\n  levelIndex = index;\n  playerX = START_X[index];\n  playerY = START_Y[index];\n  phase = 'p';\n  levelStarted = millis();\n  holdX = 0;\n  holdY = 0;\n  holdSince = levelStarted;\n  lastMove = 0;\n  Serial.print(\"Level \");\n  Serial.println(index + 1);\n}\n\nbool tryStep(int dx, int dy) {\n  if (dx == 0 && dy == 0) {\n    return false;\n  }\n  int nextX = playerX + dx;\n  int nextY = playerY + dy;\n  if (wallAt(levelIndex, nextX, nextY)) {\n    return false;\n  }\n  playerX = nextX;\n  playerY = nextY;\n  return true;\n}\n// end: player\n\nbool takeMove(int dx, int dy, unsigned long now) {\n  if (dx == 0 && dy == 0) {\n    holdX = 0;\n    holdY = 0;\n    holdSince = now;\n    return false;\n  }\n  if (dx != holdX || dy != holdY) {\n    holdX = dx;\n    holdY = dy;\n    holdSince = now;\n    lastMove = now;\n    return true;\n  }\n  if (now - holdSince >= MOVE_ARM_MS && now - lastMove >= MOVE_REPEAT_MS) {\n    lastMove = now;\n    return true;\n  }\n  return false;\n}\n\nbool readPress(unsigned long now) {\n  bool rawDown = digitalRead(SW_PIN) == LOW;\n  if (rawDown == buttonDown) {\n    buttonChanged = now;\n    return false;\n  }\n  if (now - buttonChanged < BUTTON_DEBOUNCE_MS) {\n    return false;\n  }\n  buttonDown = rawDown;\n  buttonChanged = now;\n  return rawDown;\n}\n\n// region: draw\nvoid drawPlay(unsigned long now) {\n  display.clear();\n  for (int y = 0; y < GRID; y++) {\n    for (int x = 0; x < GRID; x++) {\n      bool on = wallAt(levelIndex, x, y);\n      if (x == GOAL_X[levelIndex] && y == GOAL_Y[levelIndex]) {\n        on = (now % 800) < 600;\n      }\n      if (x == playerX && y == playerY) {\n        on = (now % 240) < 120;\n      }\n      if (on) {\n        display.setPoint(y, x, true);\n      }\n    }\n  }\n  display.update();\n}\n// end: draw\n\nvoid drawSuccess(unsigned long now) {\n  display.clear();\n  bool flash = (now / 100) % 2 == 0;\n  if (flash) {\n    display.setPoint(playerY, playerX, true);\n    display.setPoint(GOAL_Y[levelIndex], GOAL_X[levelIndex], true);\n  }\n  display.update();\n}\n\nvoid drawFinished(unsigned long now) {\n  display.clear();\n  int step = (int)((now / 80) % 28);\n  int cursor = 0;\n  for (int x = 0; x < GRID; x++) {\n    if (cursor == step) {\n      display.setPoint(0, x, true);\n    }\n    cursor++;\n  }\n  for (int y = 1; y < GRID; y++) {\n    if (cursor == step) {\n      display.setPoint(y, GRID - 1, true);\n    }\n    cursor++;\n  }\n  for (int x = GRID - 2; x >= 0; x--) {\n    if (cursor == step) {\n      display.setPoint(GRID - 1, x, true);\n    }\n    cursor++;\n  }\n  for (int y = GRID - 2; y >= 1; y--) {\n    if (cursor == step) {\n      display.setPoint(y, 0, true);\n    }\n    cursor++;\n  }\n  display.update();\n}\n\nvoid completeLevel(unsigned long now) {\n  Serial.print(\"Level \");\n  Serial.print(levelIndex + 1);\n  Serial.print(\" complete in \");\n  Serial.print(now - levelStarted);\n  Serial.println(\" ms\");\n  if (levelIndex >= LEVEL_COUNT - 1) {\n    phase = 'f';\n    Serial.print(\"All five levels in \");\n    Serial.print(now - runStarted);\n    Serial.println(\" ms. Press the joystick button to play again.\");\n  } else {\n    phase = 's';\n    successStarted = now;\n  }\n}\n\nvoid setup() {\n  pinMode(SW_PIN, INPUT_PULLUP);\n  Serial.begin(9600);\n  display.begin();\n  display.control(MD_MAX72XX::INTENSITY, 2);\n  display.clear();\n  // region: one-led\n  display.setPoint(0, 0, true);\n  display.update();\n  delay(300);\n  display.clear();\n  display.update();\n  // end: one-led\n  runStarted = millis();\n  buttonChanged = runStarted;\n  beginLevel(0);\n}\n\nvoid loop() {\n  unsigned long now = millis();\n  if (readPress(now)) {\n    if (phase == 'f') {\n      runStarted = now;\n      beginLevel(0);\n      Serial.println(\"Back to level 1.\");\n    } else {\n      beginLevel(levelIndex);\n      Serial.println(\"Level restarted.\");\n    }\n    return;\n  }\n\n  if (phase == 's') {\n    drawSuccess(now);\n    if (now - successStarted >= SUCCESS_MS) {\n      beginLevel(levelIndex + 1);\n    }\n    return;\n  }\n\n  if (phase == 'f') {\n    drawFinished(now);\n    return;\n  }\n\n  int xRaw = analogRead(X_PIN);\n  int yRaw = analogRead(Y_PIN);\n  int dx = 0;\n  int dy = 0;\n  stickStep(xRaw, yRaw, dx, dy);\n  if (takeMove(dx, dy, now) && tryStep(dx, dy)) {\n    Serial.print(\"move \");\n    Serial.print(dx);\n    Serial.print(\",\");\n    Serial.print(dy);\n    Serial.print(\" raw \");\n    Serial.print(xRaw);\n    Serial.print(\",\");\n    Serial.println(yRaw);\n    if (playerX == GOAL_X[levelIndex] && playerY == GOAL_Y[levelIndex]) {\n      completeLevel(now);\n    }\n  }\n  if (phase == 'p') {\n    drawPlay(now);\n  }\n}\n"},{"type":"text","heading":"Upload","body":"Create a sketch named led_matrix_maze and replace its contents with the program above. Board is Arduino Uno. Port is the Uno port. Click Upload. When the IDE finishes, open the Serial Monitor and set it to 9600 baud. The corner LED should flash once, then level 1 should appear and the monitor should print Level 1."},{"type":"expected","heading":"What you should observe","body":"One LED flashes in the top-left corner, then the first maze appears. Walls stay lit. One dot blinks quickly on the start square. Another square blinks slowly. That slow square is the goal."}]$mazestep$),
  (17, 4, $mazestep$Test and troubleshoot$mazestep$, $mazestep$Play the five levels$mazestep$, $mazestep$Finish each maze, then use the button and the two invert lines if a control feels backwards.$mazestep$, null, $mazestep$[{"type":"test","heading":"Play","body":"Move to the slow square on each maze. The monitor prints a time in milliseconds when a level completes. After level 5, one LED runs around the border and the monitor prints the total. Press the stick button to return to level 1. During an earlier level, the same button puts you back on that level’s start square."},{"type":"troubleshooting","heading":"If something is wrong","items":[{"problem":"The matrix stays dark","solution":"Confirm MD_MAX72XX 3.5.1, FC16_HW, DIN on D11, CLK on D13, and CS on D10. VCC must come from the red rail and GND from the blue rail. Intensity stays at 2. A charge-only USB cable can power the Uno LED and still fail to upload."},{"problem":"The maze is rotated or mirrored","solution":"Turn the module so the input header is on the right, top to bottom CLK, CS, DIN, GND, VCC. Row 0 is then the top. If the silk order differs, move the jumpers to match the silk rather than this list."},{"problem":"The stick moves the wrong way","solution":"Change INVERT_X or INVERT_Y in the sketch and upload again. Leave the pin numbers alone. A centred stick should print nothing and should not move the player."},{"problem":"The player jitters or runs away","solution":"Leave the deadzone at 80 and the repeat at 280 ms then 180 ms. A noisy module that never rests near 512 needs a larger JOY_DEADZONE, not a deleted check. Do not add delay() inside loop."},{"problem":"The button restarts more than once","solution":"SW must go to D2 and the pin mode must stay INPUT_PULLUP. The press is accepted only after 40 ms and only on the change to pressed. Holding the button should produce one restart."}]},{"type":"expected","heading":"Finished","body":"You can complete all five mazes, read each level time and the final total in the Serial Monitor, and start a new run with the joystick button."}]$mazestep$)
) as v(sort_order, stage_sort_order, stage_title, title, description, tip, blocks)
where p.slug = '25';
